// 原资格夹具只隔离关店资金门；实际Common归还、晚失败及冷截面走本域业务，未冒自然开店旅程。
#define main private_shop_transaction_fixture_main
#include "private_shop_transaction_test.cpp"
#undef main
#include "resident/domains/commerce/private_shop_closing.hpp"
#include "resident/domains/local_economy/local_economy_internal.hpp"
#include "resident/domains/tasks/shop_orders/task_shop_asset_responsibilities.hpp"
namespace {
struct ClosingTasks:TaskPrivateShopAssetResponsibilityRead {
 const CommonStore* common=nullptr;bool pending=false,fail_history=false;mutable bool observed_return=false;
 Outcome<TaskPrivateShopAssetResponsibilities> current(const TaskPrivateShopAssetScope& scope)const override{return {true,{common->state().identity,scope,common->tick(),{},pending?std::vector<StableId>{"fixture.pending"}:std::vector<StableId>{}},{}};}
 Outcome<TaskPrivateShopAssetResponsibilities> before_close(const TaskPrivateShopAssetScope& scope,const StableId& fact,Integer tick)const override{observed_return=common->wallet(scope.wallet_id)->balance==0&&common->inventory(scope.inventory_id)->lots.empty();if(fail_history)return {false,{},common_failure("InjectedClosingHistoryFailure").error};auto out=current(scope);out.value.as_of_tick=tick;out.value.closing_fact_id=fact;return out;}
};
struct ClosingTrades:GrowthLifeRead {OrderedTable<LifeActivityView> sources;std::optional<LifeActivityView> life_result(const StableId& id)const override{const auto* s=sources.find(id);return s?std::optional<LifeActivityView>{*s}:std::nullopt;}std::vector<StableId> life_fact_ids(Integer,Integer)const override{return sources.order();}};
// 外层Common唯一保存点与Shop守卫同时提交或回滚，和World候选约定一致。
Outcome<StableId> close(Fixture& f,const PrivateShopContext& x,const PrivateShopClosingQuote& q){local_economy_detail::PhaseSavepoint common(f.common);if(!common.token().ok)return {false,{},common.token().error};local_economy_detail::CandidateStateGuard<PrivateShopState> shop(f.state);auto result=close_private_shop_in_candidate(f.common,f.state,x,q);if(!result.ok)return result;auto done=common.commit();if(!done.ok)return {false,{},done.error};shop.commit();return result;}
// 成本来源是人工Growth只读夹具，财货实际从原共同recipe搬移，验证归还没有新收入。
void add_stock(Fixture& f,ClosingTrades& trades,const PrivateShopOpeningReceipt& opened){auto trade=f.common.next_id("action");check(trade.ok,"stock trade ID");check(f.common.append_fact({trade.value,"life_activity","growth"}).ok,"stock trade header");check(f.common.apply_resources({{WalletDelta{opened.wallet_id,-20,true},WalletDelta{"lessor.wallet",20,false},AddLot{"owner.bag","grain",2,{Owner::Kind::actor,"owner",{}},{}}},{}}).ok,"actual stock purchase money and bag");auto old=f.common.inventory("owner.bag")->lots.back();auto id=f.common.next_id("private_shop_stock");check(id.ok&&f.common.append_fact({id.value,"private_shop_stock_received",private_shop_module}).ok,"stocking source");AdjustLots debit;debit.inventory_id="owner.bag";debit.lots.push_back({old.id,-2});check(f.common.apply_resources({{debit,AddLot{opened.inventory_id,"grain",2,{Owner::Kind::actor,"owner",{}},{}}},{}}).ok,"actual stock transfer");auto fresh=f.common.inventory(opened.inventory_id)->lots.back();PrivateShopPurchaseFact purchase{id.value,opened.shop_id,trade.value,"grain","original.market","owner.bag",opened.inventory_id,0,2,20,{{old.id,2}},{{fresh.id,2}}};check(f.state.purchases.insert(id.value,purchase),"stock record");LifeActivityView v;v.fact_id=v.action_id=trade.value;v.kind=LifeActivityKind::trade;v.activity="buy";v.actor_id="owner";v.item_id="grain";v.quantity=2;v.amount=20;v.payer_wallet_id=opened.wallet_id;v.payee_wallet_id="lessor.wallet";v.from_inventory_id="lessor.bag";v.to_inventory_id="owner.bag";trades.sources.insert(trade.value,v);}
void closing_assets_and_history(){Fixture f;auto opened=open_private_shop(f.common,f.economy,f.state,f.context(),f.meeting(),f.quote());check(opened.ok,"open before close");ClosingTasks tasks;tasks.common=&f.common;ClosingTrades trades;add_stock(f,trades,opened.value);auto x=f.context();x.closing_tasks=&tasks;x.trades=&trades;check(validate_private_shops(x).ok,"stocked source valid");tasks.pending=true;auto rejected=preview_private_shop_closing(x,"owner",{opened.value.shop_id});check(!rejected.ok&&rejected.error.original.code=="PrivateShopTaskAssetsOutstanding","pending Task blocks close");tasks.pending=false;auto q=preview_private_shop_closing(x,"owner",{opened.value.shop_id});check(q.ok&&q.value.returned_cash==280&&q.value.stock_lots.size()==1,"only real remaining cash and goods quoted");const auto cash=f.common.wallet("owner.wallet")->balance;auto result=close(f,x,q.value);check(result.ok&&tasks.observed_return,"history reads after actual return");check(f.common.wallet("owner.wallet")->balance==cash+280&&f.common.wallet(opened.value.wallet_id)->balance==0&&f.common.inventory(opened.value.inventory_id)->lots.empty(),"equal cash legs and emptied stock");check(f.common.count("owner.bag","grain",{{Owner::Kind::actor,"owner",{}}}).value==2,"actual remaining goods returned");check(f.state.shops.find(opened.value.shop_id)->status=="closed"&&f.state.purchases.size()==1&&f.state.closings.size()==1,"permanent records retained");check(validate_private_shops(x).ok,"closed history valid");check(!preview_private_shop_management(x,"owner",PrivateShopFund{opened.value.shop_id,1}).ok,"closed capital rejected");auto saved=f.state;f.state.closings.find(result.value)->returned_cash++;check(!validate_private_shops(x).ok,"forged returned capital rejects");f.state=saved;check(preview_private_shop_opening(x,f.meeting(),"owner",{"stall"}).ok,"same premises reusable after true close");}
void closing_late_failure(){Fixture f;auto opened=open_private_shop(f.common,f.economy,f.state,f.context(),f.meeting(),f.quote());check(opened.ok,"late fixture open");ClosingTasks tasks;tasks.common=&f.common;auto x=f.context();x.closing_tasks=&tasks;auto q=preview_private_shop_closing(x,"owner",{opened.value.shop_id});check(q.ok,"late close quote");const auto common=encode_common_state(f.common.state()),shop=encode_private_shop_state(f.state);tasks.fail_history=true;auto failed=close(f,x,q.value);check(!failed.ok&&tasks.observed_return,"late responsibility failure after money return");check(compare_boundary(common,encode_common_state(f.common.state())).exact()&&compare_boundary(shop,encode_private_shop_state(f.state)).exact(),"whole Common IDs wallets stock and Shop restored");tasks.fail_history=false;f.common.state().next_instance_id=std::numeric_limits<Integer>::max();q=preview_private_shop_closing(x,"owner",{opened.value.shop_id});check(q.ok,"max ID quote still read only");const auto ids=encode_common_state(f.common.state());failed=close(f,x,q.value);check(!failed.ok&&compare_boundary(ids,encode_common_state(f.common.state())).exact(),"closing ID failure after money return rolls back");}
}
int main(){try{closing_assets_and_history();closing_late_failure();std::cout<<checks<<"/0 isolated closing checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
